//! Every NOAA Weather Radio transmitter weather.gov lists, with its location
//! and the counties it covers, whether or not anyone streams it.
//!
//! The table is `data/nwr_transmitters.json`, generated by
//! `cargo xtask nwr-transmitters` from weather.gov's station data
//! (<https://www.weather.gov/source/nwr/JS/ccl-data.js>). It places stations
//! that a stream source carries but the WeatherIndex directory doesn't list,
//! and gives alert auto-tune their county coverage.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

use crate::stations::Station;

const DATA: &str = include_str!("../data/nwr_transmitters.json");

/// One transmitter from the weather.gov table.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct Transmitter {
    pub call_sign: String,
    /// MHz, e.g. 162.450.
    pub frequency: f64,
    /// Site location, e.g. "Carrollton".
    pub site: String,
    /// Two-letter state code.
    pub state: String,
    pub lat: f64,
    pub lon: f64,
    /// `NORMAL`, `DEGRADED` or `OUT OF SERVICE` when the table was made.
    #[serde(default)]
    pub status: String,
    /// SAME county codes the transmitter covers (6 digits).
    #[serde(default)]
    pub same: Vec<String>,
}

impl Transmitter {
    /// The finder's `Station` ("Carrollton, MO").
    pub fn to_station(&self) -> Station {
        let name = if self.site.is_empty() {
            self.state.clone()
        } else if self.state.is_empty()
            || self
                .site
                .to_uppercase()
                .ends_with(&format!(", {}", self.state))
        {
            self.site.clone()
        } else {
            format!("{}, {}", self.site, self.state)
        };
        let mut station = Station::new(
            &self.call_sign,
            self.frequency,
            &name,
            self.lat,
            self.lon,
            &self.state,
        );
        station.status = self.status.clone();
        station
    }
}

#[derive(Deserialize)]
struct Table {
    transmitters: Vec<Transmitter>,
}

struct Index {
    list: Vec<Transmitter>,
    by_call_sign: HashMap<String, usize>,
}

fn index() -> &'static Index {
    static INDEX: OnceLock<Index> = OnceLock::new();
    INDEX.get_or_init(|| {
        let list = match serde_json::from_str::<Table>(DATA) {
            Ok(table) => table.transmitters,
            Err(e) => {
                tracing::error!("Bundled NOAA transmitter table is unreadable: {e}");
                Vec::new()
            }
        };
        let by_call_sign = list
            .iter()
            .enumerate()
            .map(|(i, t)| (t.call_sign.to_uppercase(), i))
            .collect();
        Index { list, by_call_sign }
    })
}

/// Every transmitter in the table.
pub fn all() -> &'static [Transmitter] {
    &index().list
}

/// The transmitter with this call sign, if weather.gov lists it.
pub fn find(call_sign: &str) -> Option<&'static Transmitter> {
    let index = index();
    index
        .by_call_sign
        .get(&call_sign.trim().to_uppercase())
        .map(|&i| &index.list[i])
}

/// `streamed` followed by every transmitter it doesn't already list, for
/// a finder that also shows stations nobody streams.
pub fn with_unstreamed(streamed: Vec<Station>) -> Vec<Station> {
    let known: std::collections::HashSet<String> = streamed
        .iter()
        .map(|s| s.call_sign.trim().to_uppercase())
        .collect();
    let mut stations = streamed;
    stations.extend(
        all()
            .iter()
            .filter(|t| !known.contains(&t.call_sign.to_uppercase()))
            .map(Transmitter::to_station),
    );
    stations
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_loads_and_covers_every_state() {
        let list = all();
        assert!(list.len() > 900, "only {} transmitters", list.len());
        for t in list {
            assert_eq!(t.state.len(), 2, "{t:?}");
            assert!((-90.0..=90.0).contains(&t.lat) && (-180.0..=180.0).contains(&t.lon));
            assert!(t.frequency > 162.0 && t.frequency < 163.0, "{t:?}");
            assert!(t.same.iter().all(|c| c.len() == 6), "{t:?}");
        }
        let missouri = list.iter().filter(|t| t.state == "MO").count();
        let north_carolina = list.iter().filter(|t| t.state == "NC").count();
        assert!(missouri > 20 && north_carolina > 15);
    }

    #[test]
    fn finds_keytesville_transmitter_by_call_sign() {
        // KZZ34 (Carrollton, MO) covers Chariton County, SAME 029041.
        let kzz34 = find(" kzz34 ").expect("KZZ34 is listed");
        assert_eq!(kzz34.state, "MO");
        assert!(kzz34.same.iter().any(|c| c == "029041"));
        let station = kzz34.to_station();
        assert_eq!(station.call_sign, "KZZ34");
        assert!(station.name.ends_with(", MO"));
        assert!(find("ZZZ99").is_none());
    }

    #[test]
    fn unstreamed_transmitters_follow_the_streamed_list() {
        let streamed = vec![Station::new("kzz34", 162.45, "Streamed", 39.4, -93.4, "MO")];
        let stations = with_unstreamed(streamed);
        assert_eq!(stations[0].name, "Streamed");
        assert_eq!(stations.len(), all().len());
        assert_eq!(
            stations
                .iter()
                .filter(|s| s.call_sign.eq_ignore_ascii_case("KZZ34"))
                .count(),
            1
        );
    }

    #[test]
    fn station_name_does_not_repeat_the_state() {
        let mut t = find("KZZ34").unwrap().clone();
        t.site = "Carrollton, MO".into();
        assert_eq!(t.to_station().name, "Carrollton, MO");
        t.site = String::new();
        assert_eq!(t.to_station().name, "MO");
    }
}
